void iriap_get_attr_by_class(struct iriap_cb *self, struct sk_buff *skb) {
    char *class_name = NULL;
    char *attr_name = NULL;

    if (!self || !skb) {
        return;
    }

    class_name = (char *)skb->data;
    if (!class_name) {
        return;
    }

    attr_name = class_name + strlen(class_name) + 1;
    if (!attr_name || (attr_name - class_name) >= skb->len) {
        return;
    }

    struct iriap_object *obj = find_object_by_name(self->objects, class_name);
    if (!obj) {
        send_error_response(skb, IRIAP_ERR_OBJECT_NOT_FOUND);
        return;
    }

    struct iriap_attribute *attr = find_attribute_by_name(obj->attributes, attr_name);
    if (!attr) {
        send_error_response(skb, IRIAP_ERR_ATTRIBUTE_NOT_FOUND);
        return;
    }

    send_value_response(skb, attr->value);
}
